import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        # Retry logic for network errors
        for attempt in range(2):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    status = resp.status
                    body = resp.read().decode('utf-8')
                    if status == 429:
                        # Retry with exponential backoff
                        for delay in [0.5, 1, 2]:
                            time.sleep(delay)
                            try:
                                req = urllib.request.Request(url)
                                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                                    status = resp.status
                                    body = resp.read().decode('utf-8')
                                    if status == 200:
                                        return body
                            except urllib.error.HTTPError as e:
                                status = e.code
                                if status == 200:
                                    return body
                            except urllib.error.URLError:
                                continue
                        raise RateLimitError("Rate limit exceeded")
                    elif 500 <= status < 600:
                        # Retry once after 1s
                        time.sleep(1)
                        try:
                            req = urllib.request.Request(url)
                            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                                status = resp.status
                                body = resp.read().decode('utf-8')
                                if status == 200:
                                    return body
                            raise ServerError("Server error")
                        except urllib.error.HTTPError as e:
                            if 500 <= e.code < 600:
                                raise ServerError("Server error")
                            raise ClientError(f"Client error: {e.code}")
                    elif 400 <= status < 500:
                        raise ClientError(f"Client error: {status}")
                    else:
                        return body
            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    for delay in [0.5, 1, 2]:
                        time.sleep(delay)
                        try:
                            req = urllib.request.Request(url)
                            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                                status = resp.status
                                body = resp.read().decode('utf-8')
                                if status == 200:
                                    return body
                        except urllib.error.HTTPError as e2:
                            status = e2.code
                            if status == 200:
                                return body
                    raise RateLimitError("Rate limit exceeded")
                elif 500 <= status < 600:
                    time.sleep(1)
                    try:
                        req = urllib.request.Request(url)
                        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                            status = resp.status
                            body = resp.read().decode('utf-8')
                            if status == 200:
                                return body
                        raise ServerError("Server error")
                    except urllib.error.HTTPError as e2:
                        if 500 <= e2.code < 600:
                            raise ServerError("Server error")
                        raise ClientError(f"Client error: {e2.code}")
                elif 400 <= status < 500:
                    raise ClientError(f"Client error: {status}")
                else:
                    raise
            except urllib.error.URLError:
                time.sleep(1)
                continue
        raise ConnectionError("Connection failed")
